import json
import requests

def execute_workflow(context: dict) -> dict:
    # Step 1: Strip and inspect container errors
    log_inspector_response = requests.post(
        "http://localhost:5001/mcp/system",
        json={
            "jsonrpc": "2.0",
            "method": "log_inspector",
            "params": {
                "container_name": context.get("container_name", "devops-vsp-sample-app"),
                "error_signatures": ["ERROR", "EXCEPTION"]
            },
            "id": 1
        }
    ).json()

    if "error" in log_inspector_response:
        return {
            "status": "error",
            "summary": "Failed to inspect container logs",
            "steps": ["Step 1: Strip and inspect container errors"],
            "rca": {}
        }

    stripped_error = log_inspector_response.get("result", {}).get("stripped_error", "")

    # Step 2: Check ServiceNow incident deduplication
    dedup_checker_response = requests.post(
        "http://localhost:5001/mcp/system",
        json={
            "jsonrpc": "2.0",
            "method": "dedup_checker",
            "params": {
                "short_description": "Application devops-vsp-sample-app Error"
            },
            "id": 2
        }
    ).json()

    if "error" in dedup_checker_response:
        return {
            "status": "error",
            "summary": "Failed to check ServiceNow incident deduplication",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication"],
            "rca": {}
        }

    if dedup_checker_response.get("result", {}).get("is_duplicate", False):
        return {
            "status": "deduplicated",
            "summary": "Incident deduplicated",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication"],
            "rca": {}
        }

    # Step 3: Correlate with Jenkins pipeline
    jenkins_response = requests.post(
        "http://localhost:5001/mcp/jenkins",
        json={
            "jsonrpc": "2.0",
            "method": "get_job_details",
            "params": {
                "job_name": context.get("jenkins_job", "devops-vsp-pipeline")
            },
            "id": 3
        }
    ).json()

    if "error" in jenkins_response:
        return {
            "status": "error",
            "summary": "Failed to correlate with Jenkins pipeline",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline"],
            "rca": {}
        }

    # Step 4: Correlate with GitHub repository
    github_response = requests.post(
        "http://localhost:5001/mcp/github",
        json={
            "jsonrpc": "2.0",
            "method": "get_repository",
            "params": {
                "repo_name": context.get("github_repo", "shakilmunavary/devops-vsp-sample-app")
            },
            "id": 4
        }
    ).json()

    if "error" in github_response:
        return {
            "status": "error",
            "summary": "Failed to correlate with GitHub repository",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline", "Step 4: Correlate with GitHub repository"],
            "rca": {}
        }

    # Step 5: Diagnose failure with Mistral AI RCA
    ai_rca_response = requests.post(
        "http://localhost:5001/mcp/system",
        json={
            "jsonrpc": "2.0",
            "method": "ai_rca",
            "params": {
                "error_log": stripped_error,
                "jenkins_job": context.get("jenkins_job", "devops-vsp-pipeline"),
                "github_repo": context.get("github_repo", "shakilmunavary/devops-vsp-sample-app")
            },
            "id": 5
        }
    ).json()

    if "error" in ai_rca_response:
        return {
            "status": "error",
            "summary": "Failed to diagnose failure with Mistral AI RCA",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline", "Step 4: Correlate with GitHub repository", "Step 5: Diagnose failure with Mistral AI RCA"],
            "rca": {}
        }

    rca_result = ai_rca_response.get("result", {})

    # Step 6: Create ServiceNow Incident with stripped error
    create_incident_response = requests.post(
        "http://localhost:5001/mcp/servicenow",
        json={
            "jsonrpc": "2.0",
            "method": "create_incident",
            "params": {
                "short_description": "Application devops-vsp-sample-app Error",
                "work_notes": f"SRE AI agent is analyzing the issue.\n\n=== STRIPPED ERROR LOG ===\n{stripped_error}",
                "urgency": context.get("snow_urgency", "2"),
                "impact": "2"
            },
            "id": 6
        }
    ).json()

    if "error" in create_incident_response:
        return {
            "status": "error",
            "summary": "Failed to create ServiceNow incident",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline", "Step 4: Correlate with GitHub repository", "Step 5: Diagnose failure with Mistral AI RCA", "Step 6: Create ServiceNow Incident with stripped error"],
            "rca": {}
        }

    incident_number = create_incident_response.get("result", {}).get("incident_number", "")

    # Step 7: Enrich ticket with RCA & Auto-Resolve
    update_incident_response = requests.post(
        "http://localhost:5001/mcp/servicenow",
        json={
            "jsonrpc": "2.0",
            "method": "update_incident",
            "params": {
                "incident_number": incident_number,
                "work_notes": f"Root Cause: {rca_result.get('root_cause', '')}\nAffected Component: {rca_result.get('affected_component', '')}\nRecommended Fix: {rca_result.get('recommended_fix', '')}",
                "state": "6",
                "close_code": "Solution Provided"
            },
            "id": 7
        }
    ).json()

    if "error" in update_incident_response:
        return {
            "status": "error",
            "summary": "Failed to update ServiceNow incident",
            "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline", "Step 4: Correlate with GitHub repository", "Step 5: Diagnose failure with Mistral AI RCA", "Step 6: Create ServiceNow Incident with stripped error", "Step 7: Enrich ticket with RCA & Auto-Resolve"],
            "rca": {}
        }

    return {
        "status": "incident_resolved",
        "summary": "Incident resolved",
        "steps": ["Step 1: Strip and inspect container errors", "Step 2: Check ServiceNow incident deduplication", "Step 3: Correlate with Jenkins pipeline", "Step 4: Correlate with GitHub repository", "Step 5: Diagnose failure with Mistral AI RCA", "Step 6: Create ServiceNow Incident with stripped error", "Step 7: Enrich ticket with RCA & Auto-Resolve"],
        "rca": rca_result
    }

if __name__ == '__main__':
    result = execute_workflow({})
    print(json.dumps(result, indent=2))
